{
  "css": ".product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  margin-bottom: 8px;
}

.product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  word-break: keep-all;
  overflow-wrap: break-word;
}

.product-identity .price-row {
  margin-top: 12px;
}

.product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: #202024;
}

.product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
}

.product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: #60606a;
}

.product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  white-space: nowrap;
}

.product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: #202024;
  margin-top: 20px;
}"
